import{_ as t,o as a,c as i,a8 as s}from"./chunks/framework.DpsX1MbM.js";const p=JSON.parse('{"title":"EAGLE3 offline disaggregated parity","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks/eagle3-disaggregated-parity.md","filePath":"sections/benchmarks/eagle3-disaggregated-parity.md","lastUpdated":1788846900000}'),r={name:"benchmarks/eagle3-disaggregated-parity.md"};function n(d,e,o,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="eagle3-offline-disaggregated-parity" tabindex="-1">EAGLE3 offline disaggregated parity <a class="header-anchor" href="#eagle3-offline-disaggregated-parity" aria-label="Permalink to &quot;EAGLE3 offline disaggregated parity&quot;">​</a></h1><p>This page preserves a historical correctness check from commit <code>40d8feff</code>. It is evidence that the offline producer/consumer path and colocated path were numerically aligned in that experiment, not a current-release performance or quality claim.</p><h2 id="qwen2-5-7b-two-h200-nodes" tabindex="-1">Qwen2.5-7B, two H200 nodes <a class="header-anchor" href="#qwen2-5-7b-two-h200-nodes" aria-label="Permalink to &quot;Qwen2.5-7B, two H200 nodes&quot;">​</a></h2><p>The comparison used the same Qwen2.5-7B model build, precomputed feature tensors, and random seed for both paths. The disaggregated consumer and the colocated baseline assembled the EAGLE3 runtime through the same training implementation. Feature tensors were byte-identical; the remaining metric differences were approximately <code>1e-6</code> to <code>1e-8</code> GPU numerical noise.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Step</th><th>Metric</th><th style="text-align:right;">Disaggregated</th><th style="text-align:right;">Colocated</th></tr></thead><tbody><tr><td style="text-align:right;">20</td><td><code>acceptance_rate</code></td><td style="text-align:right;">0.0013300</td><td style="text-align:right;">0.0013300</td></tr><tr><td style="text-align:right;">20</td><td><code>ploss</code></td><td style="text-align:right;">5.386736</td><td style="text-align:right;">5.386740</td></tr><tr><td style="text-align:right;">20</td><td><code>acc</code></td><td style="text-align:right;">0.0272590</td><td style="text-align:right;">0.0272590</td></tr><tr><td style="text-align:right;">120</td><td><code>acceptance_rate</code></td><td style="text-align:right;">0.0223610</td><td style="text-align:right;">0.0223505</td></tr><tr><td style="text-align:right;">180</td><td><code>acceptance_rate</code></td><td style="text-align:right;">0.0337013</td><td style="text-align:right;">0.0336982</td></tr></tbody></table><p>Both accuracy and the training-time acceptance proxy increased during the run. Per-step values remained noisy because the experiment used batch size 1 over 64 diverse samples. This proxy is useful for path parity; it is not the same measurement as serving-time accepted length.</p><h2 id="unified-entry-for-a-new-run" tabindex="-1">Unified entry for a new run <a class="header-anchor" href="#unified-entry-for-a-new-run" aria-label="Permalink to &quot;Unified entry for a new run&quot;">​</a></h2><p>The current equivalent recipe is <code>examples/configs/offline/disaggregated/qwen2.5-7b-eagle3-offline-disaggregated.yaml</code>. To place the offline producer and consumer on different nodes, run one checked-in command through the cluster launcher:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rcli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --per-node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;CONFIG=examples/configs/offline/disaggregated/qwen2.5-7b-eagle3-offline-disaggregated.yaml bash examples/disagg/run_offline_2node.sh&#39;</span></span></code></pre></div><p>Rank 0 invokes <code>specforge train --role producer</code>; rank 1 invokes <code>specforge train --role consumer</code>. Both nodes must resolve the config&#39;s <code>control_dir</code>, <code>store_root</code>, hidden-state input, and vocabulary mapping to the same data. Use a fresh attempt directory, then compare against the colocated <code>examples/configs/offline/colocated/qwen2.5-7b-eagle3-offline.yaml</code> recipe with the same inputs, seed, and training overrides.</p>`,10)])])}const f=t(r,[["render",n]]);export{p as __pageData,f as default};
